/** Faithful import from theory .docx (text, emphasis, tables, images). */

export type TheorySpan = {
  readonly text: string;
  readonly em?: boolean;
  readonly strong?: boolean;
  readonly mark?: boolean;
};

/** One table cell = list of paragraphs; each paragraph = spans. */
export type TheoryTableCell = readonly (readonly TheorySpan[])[];

export type TheoryBlock =
  | { readonly type: "p"; readonly spans: readonly TheorySpan[] }
  | { readonly type: "eq"; readonly text: string }
  | { readonly type: "img"; readonly src: string; readonly alt: string }
  | { readonly type: "table"; readonly rows: readonly (readonly TheoryTableCell[])[] };

export type TheorySection = {
  readonly id: string;
  readonly title: string;
  readonly blocks: readonly TheoryBlock[];
};

export type TheoryTopic = {
  readonly id: string;
  readonly title: string;
  readonly subtitle: string;
  readonly sections: readonly TheorySection[];
};

